                processed += 1;
                terminated = terminated || token == "stop";
                println!("accept");
            } else {
                rejected += 1;
                println!("reject");
            }
        } else {
            processed = std::cmp::max(processed - 1, 0);
            terminated = termination_after_rollback(terminated, token);
            println!("rollback");
        }
    }
    println!("{}", format_matcher(processed, terminated, rejected));
}
